import numpy as np


class Tensor:
    def __init__(self, data, autograd=False, creators=None,
                 creation_op=None, id=None):
        # Initialize values to what was given upon creation
        self.data = np.array(data)
        self.autograd = autograd
        self.creators = creators
        self.creation_op = creation_op

        # These fields are not given but are filled in later
        #  or are randomly autogenerated as self.id is
        self.grad = None
        if id is None:
            id = np.random.randint(0, 100000)
        self.id = id
        self.children = {}

        # If this has creators, increment their .children dicts by 1
        #   at this tensor's id key
        if self.creators is not None:
            for c in self.creators:
                c.children[self.id] = c.children.get(self.id, 0) + 1

    def all_children_accounted_for(self):
        # If all the children have a value of 0 return true
        return all(cnt == 0 for cnt in self.children.values())

    def __add__(self, other):
        # If both have autograd, record relevant information
        if self.autograd and other.autograd:
            return Tensor(self.data + other.data, autograd=True,
                          creators=[self, other], creation_op="add")
        # Otherwise just return a plain tensor
        else:
            return Tensor(self.data + other.data)

    def __neg__(self):
        # If this tensor has autograd, record the negation op
        if self.autograd:
            return Tensor(self.data * -1, autograd=True,
                          creators=[self], creation_op="neg")
        # Otherwise just return a plain tensor
        else:
            return Tensor(self.data * -1)

    def __sub__(self, other):
        # If both have autograd, record relevant information
        if self.autograd and other.autograd:
            return Tensor(self.data - other.data, autograd=True,
                          creators=[self, other], creation_op="sub")
        # Otherwise just return a plain tensor
        else:
            return Tensor(self.data - other.data)

    def __mul__(self, other):
        # If both have autograd, record relevant information
        if self.autograd and other.autograd:
            return Tensor(self.data * other.data, autograd=True,
                          creators=[self, other], creation_op="mul")
        # Otherwise just return a plain tensor
        else:
            return Tensor(self.data * other.data)

    def mm(self, x):
        # If both have autograd, record the matrix multiplication
        if self.autograd and x.autograd:
            return Tensor(self.data.dot(x.data), autograd=True,
                          creators=[self, x], creation_op="mm")
        # Otherwise just return a plain tensor
        else:
            return Tensor(self.data.dot(x.data))

    def transpose(self):
        # If this tensor has autograd, record the transpose op
        if self.autograd:
            return Tensor(self.data.transpose(), autograd=True,
                          creators=[self], creation_op="transpose")
        # Otherwise just return a plain tensor
        else:
            return Tensor(self.data.transpose())

    def sum(self, dim):
        # Encode the summed dimension in the op name so backward knows which axis to expand
        if self.autograd:
            return Tensor(self.data.sum(dim), autograd=True,
                          creators=[self], creation_op="sum_" + str(dim))
        # Otherwise just return a plain tensor
        else:
            return Tensor(self.data.sum(dim))

    def expand(self, dim, copies):
        # Insert a new axis at dim and repeat the data copies times along it
        trans_cmd = list(range(0, len(self.data.shape)))
        trans_cmd.insert(dim, len(self.data.shape))
        new_data = self.data.repeat(copies).reshape(
            list(self.data.shape) + [copies]).transpose(trans_cmd)

        # Encode the expanded dimension in the op name so backward knows which axis to sum
        if self.autograd:
            return Tensor(new_data, autograd=True,
                          creators=[self], creation_op="expand_" + str(dim))
        # Otherwise just return a plain tensor
        else:
            return Tensor(new_data)

    # These two funcs do the same thing: return self.data as str not object address
    def __repr__(self):
        return str(self.data)

    def __str__(self):
        return str(self.data)

    def backward(self, grad=None, grad_origin=None):
        # if its a plain tensor, it shouldn't do anything here
        if not self.autograd:
            return

        # If this is the starting point, grad begins as ones
        if grad is None:
            grad = Tensor(np.ones_like(self.data))

        # If a child is reporting this
        if grad_origin is not None:
            # If the child's count is 0 it is double backpropping, which shouldn't happen
            if self.children[grad_origin.id] == 0:
                raise Exception("cannot backprop more than once")

            # Otherwise, decrement it's count
            else:
                self.children[grad_origin.id] -= 1

        # if self has no grad, then set it to grad because you can't add to none
        if self.grad is None:
            self.grad = grad
        else:
            # increment gradient
            self.grad += grad

        # The gradient should not have its own graph
        assert(grad.autograd == False)

        # If this has creators AND
        # If all the children are accounted for or there is no grad_origin(it was the first)
        #  then go backward into its creators
        if self.creators is not None and (self.all_children_accounted_for() or grad_origin is None):
            if self.creation_op == "add":
                self.creators[0].backward(Tensor(self.grad.data), self)
                self.creators[1].backward(Tensor(self.grad.data), self)

            elif self.creation_op == "neg":
                # Pass the negated gradient back to the creator
                self.creators[0].backward(self.grad.__neg__(), self)

            elif self.creation_op == "sub":
                # First creator gets positive grad, second creator gets negated grad
                self.creators[0].backward(Tensor(self.grad.data), self)
                self.creators[1].backward(self.grad.__neg__(), self)

            elif self.creation_op == "mul":
                # Each creator gets grad multiplied by the other creator's data
                c0, c1 = self.creators
                c0.backward(Tensor(self.grad.data * c1.data), self)
                c1.backward(Tensor(self.grad.data * c0.data), self)

            elif self.creation_op == "mm":
                # Compute matrix multiplication gradients on .data and wrap as plain Tensors
                c0, c1 = self.creators
                c0.backward(Tensor(self.grad.data.dot(c1.data.T)), self)
                c1.backward(Tensor(c0.data.T.dot(self.grad.data)), self)

            elif self.creation_op == "transpose":
                # Transpose the gradient back to match the creator's original shape
                self.creators[0].backward(self.grad.transpose(), self)

            elif "sum" in self.creation_op:
                # Read the summed axis back out and expand the gradient along that dim
                dim = int(self.creation_op.split("_")[1])
                ds = self.creators[0].data.shape[dim]
                self.creators[0].backward(self.grad.expand(dim, ds), self)

            elif "expand" in self.creation_op:
                # Read the expanded axis back out and sum the gradient over that dim
                dim = int(self.creation_op.split("_")[1])
                self.creators[0].backward(self.grad.sum(dim), self)


if __name__ == "__main__":
    a = Tensor([1, 2, 3, 4, 5], autograd=True)
    b = Tensor([2, 2, 2, 2, 2], autograd=True)
    c = Tensor([5, 4, 3, 2, 1], autograd=True)
    d = a + b
    e = b + c
    f = d + e
    f.backward(Tensor(np.array([1, 1, 1, 1, 1])))
    print(b.grad.data)  # [2 2 2 2 2]

    x = Tensor([1, 2, 3, 4, 5], autograd=True)
    y = Tensor([1, 1, 1, 1, 1], autograd=True)
    s = x + y  # not a leaf, and used twice below
    loss = (s + a) + (s + c)  # a, c: the tensors from the block above
    loss.backward(Tensor(np.array([1, 1, 1, 1, 1])))
    print(x.grad.data)  # [2 2 2 2 2]

    # Check non-leaf reuse through mm
    X = Tensor([[1., 2.], [3., 4.]], autograd=True)
    W = Tensor([[0.5, -0.5], [1., 0.25]], autograd=True)
    A = Tensor([[1., 0.], [2., 1.]], autograd=True)
    B = Tensor([[0., 1.], [1., 3.]], autograd=True)
    h = X.mm(W)
    (h.mm(A) + h.mm(B)).sum(0).sum(0).backward()
    print(W.grad.data.tolist())  # [[8.0, 28.0], [12.0, 42.0]]